/// <summary>
///    AVA <c>dialogGetDataAreaId</c> method.
/// </summary>
/// <returns>
///    <c>DataAreaId</c> as return value
/// </returns>
public static DataAreaId dialogGetDataAreaId()
{
    Dialog          dialog;
    DialogGroup     dialogGroup;
    DialogField     dialogDataAreaId;
    DataAreaId      locDataAreaId;

    dialog = new Dialog(strfmt("@SYS82282", "@NDX:NXACopyBPRequestToUC"));

    dialogGroup         = dialog.addGroup();
    dialogGroup.caption("@NDX:NXACopyBPRequestToUC");
    dialogDataAreaId    = dialog.addFieldValue(extendedTypeStr(DataAreaId), locDataAreaId);

    dialog.run();

    if (dialog.closedOk())
    {
        //get values from the dialog fields
        locDataAreaId    = dialogDataAreaId.value();
    }
    else
    {
        locDataAreaId = '';
    }

    return locDataAreaId;
}

/// <summary>
