    }

    return locHCMWorkerRecId;
}

/// <summary>
///    AVA <c>dialogGetFieldWorker</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///    <c>HcmWorkerRecId</c> as return value
/// </returns>
public static HcmWorkerRecId dialogGetFieldWorker(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID)
{
    Dialog          dialog;
    DialogGroup     dialogGroup;
    DialogField     dialogHCMWorkerRecId;
    HcmWorkerRecId  locHCMWorkerRecId;

    #define.ADM('ADM')

    locHCMWorkerRecId = KCS_KBVResponsibilitiesTable::find(_kcs_KBVBuildingProjectID, #ADM).smmWorker;

    dialog = new Dialog(strfmt("@SYS82282", "@NDX:NXAFieldWorker"));

    dialogGroup             = dialog.addGroup();
    dialogGroup.caption("@NDX:NXASetFieldWorker");
    dialogHCMWorkerRecId    = dialog.addFieldValue(extendedTypeStr(HcmWorkerRecId), locHCMWorkerRecId);

    dialog.run();

    if (dialog.closedOk())
    {
        //get values from the dialog fields
        locHCMWorkerRecId    = dialogHCMWorkerRecId.value();
    }
    else
    {
        locHCMWorkerRecId = 0;
    }

    return locHCMWorkerRecId;
}

/// <summary>
///    AVA <c>isBPClosed</c> method.
/// </summary>
/// <param name="_kcs_KBVStatus">
///    <c>KCS_KBVStatus</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_tableId">
///    <c>TableId</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public static boolean isBPClosed(   KCS_KBVStatus               _kcs_KBVStatus,
                                    KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                    TableId                     _tableId)
{
    SalesQuotationTable         salesQuotationTable;
    KCS_KBVBPCompanySpecific    kCS_KBVBpCompanySpecific;

    switch (_kcs_KBVStatus)
    {
        case KCS_KBVStatus::Declined:
        case KCS_KBVStatus::Lost:
        case KCS_KBVStatus::Won:
        case KCS_KBVStatus::Locked:
            return true;
        //bei teilweise gewonnen weitere Prüfung notwendig
        case KCS_KBVStatus::PartialWon:
            switch (_tableId)
            {
                case tablenum(KCS_KBVBPCompanySpecific):
                    //all quotations final
                    while select salesQuotationTable
                    where   salesQuotationTable.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
                    {
                        if(!salesQuotationTable.avaIsClosed())
                        {
                            return false;
                        }
                    }

                    if( (   select count(recid) 
                            from salesQuotationTable
                            where salesQuotationTable.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID).RecId  )
                    {
                        return true;
                    }
                    else
                    {
                        return false;
                    }

                case tablenum(KCS_KBVBuildingProjectTable):
                    //all UC spezific records final
                    while select crosscompany kCS_KBVBpCompanySpecific
                    where kCS_KBVBpCompanySpecific.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
                    {
                        if(kCS_KBVBpCompanySpecific.KCS_KBVStatus != KCS_KBVStatus::PartialWon)
                        {
                            if(!kCS_KBVBpCompanySpecific.isClosed())
                            {
                                return false;
                            }
                        }
                    }

                    if((select crosscompany count(recid) 
                        from kCS_KBVBpCompanySpecific
                        where kCS_KBVBpCompanySpecific.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID).RecId)
                    {
                        return true;
                    }
                    else
                    {
                        return false;
                    }
            }
        default:
            return false;
    }
}

/// <summary>
///    AVA <c>getTodayUser</c> method.
/// </summary>
/// <returns>
