/// <summary>
///    AVA <c>getAllBPCompanies based on KCS_KBVCompPrio</c> method.
/// </summary>
/// <param name="_excludeRico">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>container</c> as return value
/// </returns>
public static server container getAllBPCompanies(boolean _excludeRico = false)
{
    container       retVal;

    //CompanyInfo     locCompanyInfo;
    KCS_KBVCompPrio locKCS_KBVCompPrio;

    DataAreaId      locDataAreaIdRico;

    int         i;

    #define.datCompany('DAT')

    if(_excludeRico)
    {
        locDataAreaIdRico = strUpr(KCS_KBVParameters::find().AVADataAreaIdRICO);
    }

    i = 1;
    /*
    while select locCompanyInfo
    {
        if (strUpr(locCompanyInfo.DataArea) != #datCompany)
        {
            retVal  = conIns(retVal, i, locCompanyInfo.DataArea);
            i++;
        }
    }
    */
    // get companies from prio list
    while select locKCS_KBVCompPrio
    {
        if (    strUpr(locKCS_KBVCompPrio.Company) != #datCompany
            &&  strUpr(locKCS_KBVCompPrio.Company) != locDataAreaIdRico)
        {
            retVal  = conIns(retVal, i, locKCS_KBVCompPrio.Company);
            i++;
        }
    }

    return retVal;
}

/// <summary>
///    AVA <c>getAllBPCompanies based on CompanyInfo</c> method.
/// </summary>
/// <param name="_excludeRico">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>container</c> as return value
/// </returns>
public static server container getAllCompanies(boolean _excludeRico = false)
{
    container       retVal;

    CompanyInfo     locCompanyInfo;

    DataAreaId      locDataAreaIdRico;

    int         i;

    #define.datCompany('DAT')

    if(_excludeRico)
    {
        locDataAreaIdRico = strUpr(KCS_KBVParameters::find().AVADataAreaIdRICO);
    }

    i = 1;

    while select locCompanyInfo
    {
        if (    strUpr(locCompanyInfo.DataArea) != #datCompany
            &&  strUpr(locCompanyInfo.DataArea) != locDataAreaIdRico    )
        {
            retVal  = conIns(retVal, i, locCompanyInfo.DataArea);
            i++;
        }
    }

    return retVal;
}

