public static str container2seperatedStr(   container   _textContainer,
                                            str         _seperator      = ', ',
                                            boolean     _sort           = false )
{
    str         retVal;

    int         i;
    container   locContainer;
    DataAreaId  locDataAreaId;

    if(_sort)
    {
        locContainer    = AVAKBVBuildingProjectHelper::containerSort(_textContainer);
    }
    else
    {
        locContainer    = _textContainer;
    }

    for (i = 1; i <= conlen(locContainer); i++)
    {
        locDataAreaId   = conpeek(locContainer, i);
        if(i > 1)
        {
            retVal      = retVal + _seperator;
        }
        retVal          = retVal + locDataAreaId;
    }
    return retVal;
}

public static container containerSort(container _textContainer)
{
    container   retVal;

    container   locContainer;
    str         locTempStr1;
    str         locTempStr2;
    int         locCounter1;
    int         locCounter2;

    locContainer = _textContainer;

    // Sort the container
    for (locCounter1 = 1; locCounter1 <= conlen(locContainer); locCounter1++)
    {
        for (locCounter2 = locCounter1 + 1; locCounter2 <= conlen(locContainer); locCounter2++)
        {
            locTempStr1 = conpeek(locContainer, locCounter2);
            locTempStr2 = conpeek(locContainer, locCounter1);

            if (locTempStr1 < locTempStr2)
            {
                locContainer = condel(locContainer, locCounter2, 1);
                locContainer = conins(locContainer, locCounter2, locTempStr2);
                locContainer = condel(locContainer, locCounter1, 1);
                locContainer = conins(locContainer, locCounter1, locTempStr1);
            }
        }
    }
    retVal = locContainer;

    return retVal;
}
